function openDataDetail(searchItem){var kind=searchItem.kind,id=searchItem.id,item=homeDataResource(kind,id);if(!item)return;document.querySelectorAll('.data-detail-mask').forEach(function(node){node.remove()});var state={tab:kind==='database'?'related':'preview',page:1},mask=document.createElement('div');mask.className='data-detail-mask';function content(){if(kind==='database')return '<div class="data-detail-tabs"><button class="'+(state.tab==='related'?'active':'')+'" data-home-data-tab="related">关联数据表 <span>'+item.tables.length+'</span></button><button class="'+(state.tab==='auth'?'active':'')+'" data-home-data-tab="auth">授权信息 <span>'+homeDataGrants('database',item).length+'</span></button></div><div class="data-detail-tab-content">'+(state.tab==='auth'?homeDataAuthorizations('database',item):homeDatabaseRelated(item))+'</div>';return '<div class="data-detail-tabs"><button class="'+(state.tab==='preview'?'active':'')+'" data-home-data-tab="preview">数据预览</button><button class="'+(state.tab==='fields'?'active':'')+'" data-home-data-tab="fields">关联数据项 <span>'+item.fields.length+'</span></button><button class="'+(state.tab==='auth'?'active':'')+'" data-home-data-tab="auth">授权信息 <span>'+homeDataGrants('table',item).length+'</span></button><button class="'+(state.tab==='explore'?'active':'')+'" data-home-data-tab="explore">数据探查</button></div><div class="data-detail-tab-content">'+(state.tab==='preview'?homeTablePreview(item,state.page):state.tab==='fields'?homeTableFields(item):state.tab==='auth'?homeDataAuthorizations('table',item):homeTableExploration(item))+'</div>'}function render(){mask.innerHTML='<aside class="data-detail-drawer" role="dialog" aria-modal="true"><header class="data-detail-header"><div class="data-detail-title"><i>'+homeDataIcon(kind)+'</i><span><small>'+(kind==='database'?'数据库':'数据表')+'</small><h2>'+esc(item.name)+'</h2><p>'+esc(item.english)+'</p></span></div><button data-home-data-close>×</button></header><section class="data-detail-overview"><div class="data-detail-tags"><button data-home-data-tag>＋ 标签</button><span>'+homeDataTags(item)+'</span></div>'+homeDataMetadata(kind,item)+'</section><main>'+content()+'</main></aside>';bind()}function bind(){mask.querySelectorAll('[data-home-data-close]').forEach(function(button){button.addEventListener('click',function(){mask.remove()})});mask.querySelectorAll('[data-home-data-tab]').forEach(function(button){button.addEventListener('click',function(){state.tab=button.dataset.homeDataTab;state.page=1;render()})});mask.querySelectorAll('[data-home-data-page]').forEach(function(button){button.addEventListener('click',function(){if(button.disabled)return;state.page=Number(button.dataset.homeDataPage);render()})});mask.querySelectorAll('[data-home-related-table]').forEach(function(button){button.addEventListener('click',function(){mask.remove();openDataDetail({kind:'table',id:button.dataset.homeRelatedTable})})});var tag=mask.querySelector('[data-home-data-tag]');if(tag)tag.addEventListener('click',function(){tag.textContent='标签功能请在资源管理中操作'});var refresh=mask.querySelector('[data-home-refresh-sample]');if(refresh)refresh.addEventListener('click',function(){refresh.textContent='已获取最新数据'});var explore=mask.querySelector('[data-home-reexplore]');if(explore)explore.addEventListener('click',function(){explore.textContent='探查任务已提交'})}mask.addEventListener('click',function(e){if(e.target===mask)mask.remove()});document.body.appendChild(mask);render()}

