function cleanFilterLabel(label){var copy=label.cloneNode(true);copy.querySelectorAll('input,em,.tree-toggle').forEach(function(node){node.remove()});return copy.textContent.replace(/[└▾▸]/g,'').replace(/\s+/g,' ').trim()}
function resultRowMatches(row,groups,query,author){var text=(row.textContent+' '+(row.dataset.resultPath||'')+' '+(row.dataset.resultTags||'')+' '+(row.dataset.resultType||'')).toLowerCase();if(query&&text.indexOf(query.toLowerCase())<0)return false;if(author&&text.indexOf(author.toLowerCase())<0)return false;return groups.every(function(group){return group.values.some(function(value){var title=group.title,target=value.toLowerCase();if(title.indexOf('资源目录')>-1){return target===tenantRoot().toLowerCase()||(row.dataset.resultPath||'').toLowerCase().indexOf(target)>-1}if(title.indexOf('标签')>-1)return (row.dataset.resultTags||'').toLowerCase().indexOf(target)>-1;if(title.indexOf('类型')>-1)return (row.dataset.resultType||'').toLowerCase().indexOf(target.replace(' 文档',''))>-1;return text.indexOf(target)>-1})})}
function applyResultFilter(aside){if(!aside)return;var shell=aside.closest('.home-filtered-result'),rows=Array.from(shell.querySelectorAll('[data-result-row]')),query=(aside.querySelector('.filter-search input').value||'').trim(),authorInput=shell.querySelector('[data-doc-author]'),author=authorInput?(authorInput.value||'').trim():'',groups=[];aside.querySelectorAll('.filter-block').forEach(function(block){var checked=Array.from(block.querySelectorAll('[data-filter-choice]:checked'));if(!checked.length)return;groups.push({title:(block.querySelector('h3').childNodes[0].nodeValue||'').trim(),values:checked.map(function(input){return cleanFilterLabel(input.closest('label'))})})});var visible=0;rows.forEach(function(row){var show=resultRowMatches(row,groups,query,author);row.hidden=!show;if(show)visible++});var active=!!(query||author||groups.length),shown=active?visible:Number(shell.dataset.defaultCount||visible);shell.querySelectorAll('[data-result-count]').forEach(function(node){node.textContent=shown});var empty=shell.querySelector('.result-filter-empty');if(empty)empty.hidden=visible>0;var feedback=aside.querySelector('.filter-feedback'),choiceCount=aside.querySelectorAll('[data-filter-choice]:checked').length;if(feedback)feedback.textContent=active?'已应用 '+choiceCount+' 项目录/类型条件，筛选出 '+shown+' 条结果':'当前未限定筛选范围';if(aside.dataset.filterKind==='文档'){shell.querySelectorAll('[data-related-visual]').forEach(function(card){card.hidden=active&&(visible===0||Number(card.dataset.resultIndex)>=Math.max(1,visible))})}}
